styl:
.b-iq-hero-13 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-hero-13 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-iq-hero-13 {  background: url("https://fsms.quadcode.com/storage/public/d7/76/lsqnsqgk5ucdfmpg/2-3-5-bcg.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.b-iq-hero-13 .w280 {  width: 100%;
  max-width: 280px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-13 .w280 {  max-width: 100% !important;  }
}
.brad-full.b-iq-hero-13 {  border-radius: 32px !important;  }
.b-iq-hero-13 .butt-link {  font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px;  }
.b-iq-hero-13 .data {  display: inline-block;
  padding: 6px 16px;
  background: url("https://fsms.quadcode.com/storage/public/d7/ae/a4qnsqgk5ucdfoj0/bg-data1.png") center top no-repeat;
  background-size: cover;
  border-radius: 12px;
  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 16px;
  line-height: 20px;
  color: #ff8516;
  text-align: left;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-13 .data {  font-size: 14px !important;  }
}
.b-iq-hero-13 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  color: #f9f9f9;
  word-break: break-word;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-13 .white-title {  font-size: 26px !important;
